    _construct_direct_gsn_basis_ys_sminus1_block_4!(coeffs, lambda, m, sn, sn2, sn3, sn4, sn5, sn6, sn7, sn8, sn9, cs)
    _construct_direct_gsn_basis_ys_sminus1_block_5!(coeffs, lambda, m, sn, sn2, sn3, sn4, sn5, sn6, sn7, sn8, sn9, cs)
    _construct_direct_gsn_basis_ys_sminus1_block_6!(coeffs, lambda, m, sn, sn2, sn3, sn4, sn5, sn6, sn7, sn8, sn9, cs)
